import{_ as i,o as s,c as r,a7 as d,j as t,a as o,t as n}from"./chunks/framework.D9zuiyJR.js";const f=JSON.parse('{"title":"CLI","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://zilero232.github.io/commit-jazzer/reference/cli"}]]},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1792424312000}'),c={name:"reference/cli.md"};function l(a,e,h,m,p,g){return s(),r("div",null,[e[10]||(e[10]=d('<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h1><p>The package installs one command under two names: <code>jazzer</code> and <code>commit-jazzer</code>.</p><h2 id="jazzer-options-git-commit-arguments" tabindex="-1"><code>jazzer [options] [-- &lt;git commit arguments&gt;]</code> <a class="header-anchor" href="#jazzer-options-git-commit-arguments" aria-label="Permalink to &quot;`jazzer [options] [-- &lt;git commit arguments&gt;]`&quot;">​</a></h2><p>Asks the questions, shows the message and runs <code>git commit</code>. Exits with git&#39;s exit code.</p><h3 id="answers" tabindex="-1">Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;Answers&quot;">​</a></h3><p>Each flag answers its question, which is then not asked. An empty value (<code>--breaking &quot;&quot;</code>) answers with nothing. A flag for a question that is not in <code>availablePromptQuestions</code> still goes into the message.</p><table tabindex="0"><thead><tr><th>Option</th><th>Answers</th></tr></thead><tbody><tr><td><code>-t, --type &lt;type&gt;</code></td><td>Commit type, e.g. <code>feat</code>.</td></tr><tr><td><code>-s, --scope &lt;scope&gt;</code></td><td>Scope (the component).</td></tr><tr><td><code>-m, --title &lt;title&gt;</code></td><td>Title.</td></tr><tr><td><code>-b, --body &lt;text&gt;</code></td><td>Description; <code>|</code> starts a new line.</td></tr><tr><td><code>--breaking &lt;text&gt;</code></td><td>Breaking change; adds <code>!</code> to the header.</td></tr><tr><td><code>-i, --issues &lt;ids&gt;</code></td><td>Related issues, e.g. <code>&quot;12, 34&quot;</code>.</td></tr><tr><td><code>--comment &lt;text&gt;</code></td><td>Extra body paragraph.</td></tr></tbody></table>',7)),t("p",null,[e[0]||(e[0]=o("Flags are validated like typed answers: an unknown type, a scope outside ",-1)),e[1]||(e[1]=t("code",null,"scopes",-1)),e[2]||(e[2]=o(" with ",-1)),e[3]||(e[3]=t("code",null,"allowCustomScopes: false",-1)),e[4]||(e[4]=o(", a title over the limit, a line break in a header field or parentheses in the scope is an error. So is an answer the template never writes (",-1)),e[5]||(e[5]=t("code",null,"--breaking",-1)),e[6]||(e[6]=o(" with a template without ",-1)),t("code",null,n(a.breaking),1),e[7]||(e[7]=o("), and ",-1)),e[8]||(e[8]=t("code",null,"--retry",-1)),e[9]||(e[9]=o(" with answers.",-1))]),e[11]||(e[11]=d('<h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>-y, --yes</code></td><td>No confirmation; only required questions without a flag are asked.</td></tr><tr><td><code>-n, --dry-run</code></td><td>Print the message to stdout instead of committing. Does not need staged changes.</td></tr><tr><td><code>-r, --retry</code></td><td>Commit the last message again, without questions.</td></tr><tr><td><code>-c, --config &lt;path&gt;</code></td><td>Use this config file instead of searching. Also <code>$JAZZER_CONFIG</code>.</td></tr><tr><td><code>--banner</code>, <code>--no-banner</code></td><td>Show or hide the banner for this run.</td></tr><tr><td><code>-a, --all</code></td><td><code>git commit --all</code>.</td></tr><tr><td><code>--amend</code></td><td><code>git commit --amend</code>.</td></tr><tr><td><code>--no-verify</code></td><td><code>git commit --no-verify</code>.</td></tr><tr><td><code>-h, --help</code></td><td>Show the help.</td></tr><tr><td><code>-v, --version</code></td><td>Show the version.</td></tr></tbody></table><p>Everything after <code>--</code> goes to <code>git commit</code> unchanged, files included:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jazzer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --author</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Jane &lt;jane@example.com&gt;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jazzer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/parser.ts</span></span></code></pre></div><p>Without a terminal (CI, scripts, pipes) nothing is asked and nothing is guessed from the branch: optional answers without a flag stay empty, and a missing required one is an error naming its flag.</p><h2 id="jazzer-alias" tabindex="-1"><code>jazzer :&lt;alias&gt;</code> <a class="header-anchor" href="#jazzer-alias" aria-label="Permalink to &quot;`jazzer :&lt;alias&gt;`&quot;">​</a></h2><p>Commits the answers of an <a href="/commit-jazzer/guide/configuration#frequent-commits">alias</a> from the config, without questions or confirmation. Answer flags override the alias: <code>jazzer :deps -i 31</code>. <code>--alias &lt;name&gt;</code> is the same.</p><h2 id="jazzer-init" tabindex="-1"><code>jazzer init</code> <a class="header-anchor" href="#jazzer-init" aria-label="Permalink to &quot;`jazzer init`&quot;">​</a></h2><p>Creates <code>jazzer.config.json</code> in the root of the repository (the current directory outside one). With a config present it exits with 1, unless <code>--force</code> replaces <code>jazzer.config.json</code>/<code>.ts</code>; with <code>--hook</code> or <code>--lint</code> it keeps the config and only installs the hooks. A config in <code>.jazzerrc</code> or <code>package.json</code> is never replaced.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--ts</code></td><td>Write <code>jazzer.config.ts</code> instead.</td></tr><tr><td><code>--hook</code></td><td>Also install the <code>prepare-commit-msg</code> hook that asks the questions on <code>git commit</code>.</td></tr><tr><td><code>--lint</code></td><td>Also install the <code>commit-msg</code> hook that runs <code>jazzer lint</code> on every message.</td></tr><tr><td><code>--remove-hook</code></td><td>Remove the hooks <code>init</code> installed; hooks written by someone else stay.</td></tr><tr><td><code>-f, --force</code></td><td>Replace <code>jazzer.config.json</code> or <code>jazzer.config.ts</code> (leaving one of them). Other configs and other hooks are never replaced.</td></tr></tbody></table><p>Hooks go to <code>.husky/</code> when husky runs the hooks, and to git&#39;s hooks directory otherwise (<code>core.hooksPath</code> and worktrees are respected). They run the project&#39;s <code>commit-jazzer</code>, then a global one, and do nothing when neither is installed.</p><h2 id="jazzer-lint-file" tabindex="-1"><code>jazzer lint [file]</code> <a class="header-anchor" href="#jazzer-lint-file" aria-label="Permalink to &quot;`jazzer lint [file]`&quot;">​</a></h2><p>Checks a commit message against the config: the <code>type(scope): subject</code> header, the type, a closed scope list, a non-empty subject, <code>headerMaxLength</code>, the blank line after the header and <code>bodyLineLength</code> for body lines. Reads <code>.git/COMMIT_EDITMSG</code> without a file. git&#39;s comment lines (<code>core.commentChar</code>) and the diff of <code>git commit -v</code> are ignored; merges, reverts, reapplies and <code>fixup!</code> commits pass. Exits with 1 when something is wrong.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>-c, --config &lt;path&gt;</code></td><td>Use this config file.</td></tr></tbody></table><h2 id="jazzer-hook-file-source" tabindex="-1"><code>jazzer hook &lt;file&gt; [source]</code> <a class="header-anchor" href="#jazzer-hook-file-source" aria-label="Permalink to &quot;`jazzer hook &lt;file&gt; [source]`&quot;">​</a></h2><p>Fills the message file from a <code>prepare-commit-msg</code> hook; <code>file</code> and <code>source</code> are the hook&#39;s <code>$1</code> and <code>$2</code>. Commits that already have a message (<code>message</code>, <code>template</code>, <code>merge</code>, <code>squash</code>, <code>commit</code> sources) and commits without a terminal are left alone.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>-c, --config &lt;path&gt;</code></td><td>Use this config file.</td></tr></tbody></table><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>Committed, printed with <code>--dry-run</code>, <code>init</code> or <code>lint</code> succeeded, or <code>hook</code> left a commit alone.</td></tr><tr><td><code>1</code></td><td>Invalid arguments, config or answers; blocked words; nothing staged; a cancelled confirmation; a message <code>lint</code> rejects.</td></tr><tr><td>other</td><td>A failed <code>git commit</code>: its own exit code.</td></tr><tr><td><code>130</code></td><td>Interrupted with Ctrl+C.</td></tr></tbody></table>',19))])}const k=i(c,[["render",l]]);export{f as __pageData,k as default};
